abla H_d ({ f y})}{\infty} &\leq {  rac{1-\varepsilon}{R}} \enspace. \end{align} }

For any $\lambda>0$, for integer $d\geq 1$, for $s\geq 1$, for ${ f x}=({ f x}_1, \ldots, { f x}_d) \in \mathbb{R}^d_{>0}$ and ${ f m}=({ f m}_1, \ldots, { f m}_d)\in \mathbb{R}^d_{\geq 0}$, the following holds: there exists $ ar{x}>0$ and integer $0\leq k\leq d$ such that  egin{align}
onumber {\psi} (F_d({ f x})) 	imes \sum
olimits_{i\in [d]}  rac{{ f m}_i }{{\psi}({ f x}_i)} \left| \left .  rac{\partial }{\partial z_i}F_d({ f z}) ight|_{{ f z} ={ f x}} ight| & \leq \left( {\Xi}(s, k,  ar{x}) ight)^{1/s} 	imes 
orm{ { f m}}{s} \enspace. \end{align}

Let $\Upsigma^{\Lambda,	au}_G$ be the $(V	imes \Lambda)	imes (V	imes \Lambda)$ covariance matrix defined with respect to $\mu^{\Lambda, 	au}$. That is, for any $u,v\in V\setminus \Lambda$ we have  egin{align}
onumber \Upsigma^{\Lambda,	au}_G(v,u) &=\mu^{\Lambda, 	au}_{(v,u)}((+1,+1))-\mu^{\Lambda, 	au}_{v}(+1)\cdot \mu^{\Lambda, 	au}_{u}(+1)\enspace. \end{align} A straightforward observation is that $\Upsigma^{\Lambda,	au}_G$ is symmetric. W.l.o.g. in this proof, assume that the diagonal entries of $\Upsigma^{\Lambda,	au}_G$ are non-zero. Note that for any $v\in V\setminus \Lambda$ we have that  egin{align} \UpM(v,v)= \sqrt{\Upsigma^{\Lambda,	au}_G(v,v)}\enspace. \end{align} Furthermore, it is standard to show, e.g. see \cite{VigodaSpectralInd}, that $\Upsigma^{\Lambda,	au}_G$ and ${\mathcal{I}}^{\Lambda,	au}_G$ satisfy that ${\mathcal{I}}^{\Lambda,	au}_G(u,v)=  rac{\Upsigma^{\Lambda,	au}_G(u,v)}{\Upsigma^{\Lambda,	au}_G(u,u)}.$ Since $\Upsigma^{\Lambda,	au}_G$ is symmetric, this relation implies that  egin{align}
onumber \Upsigma^{\Lambda,	au}_G(u,u) \cdot {\mathcal{I}}^{\Lambda,	au}_G(u,v) & =\Upsigma^{\Lambda,	au}_G(v,v) \cdot {\mathcal{I}}^{\Lambda,	au}_G(v,u) \enspace. \end{align} Then, a simple rearrangement and \eqref{eq:UpMVsCovMat} imply that  egin{align}
onumber 	extstyle  rac{\UpM(u,u)}{\UpM(v,v) } \cdot {\mathcal{I}}^{\Lambda,	au}_G(u,v)& 	extstyle =  rac{\UpM(v,v)}{\UpM(u,u) } \cdot {\mathcal{I}}^{\Lambda,	au}_G(v,u) \enspace. \end{align} The l.h.s. in the above equation corresponds to the entry $(\UpM\cdot {\mathcal{I}}^{\Lambda,	au}_G \cdot \UpM^{-1})(u,v)$, while the r.h.s. corresponds to $(\UpM\cdot {\mathcal{I}}^{\Lambda,	au}_G \cdot \UpM^{-1})(v,u)$. The claim follows.

In what follows, we abbreviate $\cadmiumgreen{\UpH}_{G,k}$ to $ yzantine{\UpH}$. Let the vector ${ f x} \in \mathbb{R}^{\iris{{\mathcal{E}}}_k}$ be such that for any $R\in \iris{{\mathcal{E}}}_k$ we have  egin{align} { f x}(R)&= rac{1}{\sqrt{2}}\left( \mathds{1}\{R=P\} + \mathds{1}\{R=Q^{-1}\} ight)\enspace. \end{align} We have that  egin{align} 
onumber { f x}^T ( yzantine{\UpH}^{\ell} \cdot \UpR){ f x}&= rac{1}{2}\left(( yzantine{\UpH}^{\ell} \cdot \UpR)(P,Q^{-1}) +( yzantine{\UpH}^{\ell} \cdot \UpR)(Q^{-1}, Q^{-1})+( yzantine{\UpH}^{\ell} \cdot \UpR)(P,P)+ ( yzantine{\UpH}^{\ell} \cdot \UpR)(Q^{-1}, P) ight)\enspace. \end{align} Recalling the definition of matrix $ yzantine{\UpH}^{\ell}\cdot \UpR$, we have  egin{align} 
onumber  yzantine{\UpH}^{\ell}(P,Q) =( yzantine{\UpH}^{\ell}\cdot \UpR)(P,Q^{-1})=( yzantine{\UpH}^{\ell} \cdot \UpR)(Q^{-1},P) \enspace, \end{align} the last equation follows since $ yzantine{\UpH}^{\ell} \cdot \UpR$ is symmetric. All the above imply that  egin{align} 
onumber  yzantine{\UpH}^{\ell}(P,Q) \leq { f x}^T \cdot ( yzantine{\UpH}^{\ell} \cdot \UpR) \cdot { f x} \leq 
orm{  yzantine{\UpH}^{\ell} \cdot \UpR}{2}=\sigma_{k,\ell} \enspace. \end{align} The last inequality above follows from the fact that $ yzantine{\UpH}^{\ell}\cdot \UpR$ is symmetric, with maximum eigenvalue $\sigma_{k,\ell}$. The claim follows.

It suffices to show that any $d>0$ and any ${ f y}\in [-\infty, +\infty]^d$ we have  egin{align} 
orm{
abla H_d ({ f y})}{\infty} &\leq  rac{| eta-1|}{ eta +1} \enspace. \end{align} Before showing that \eqref{eq:Target4thrm:SI4Ising} is true, let us show how it implies \eqref{eq:lemma:IsingInfNormBound}. That is, we show that for any $ eta \in {\mathbb{U}_{m Ising}}(R,\varepsilon)$, we have that $ rac{| eta-1|}{ eta +1}\leq  rac{1-\zeta}{R}$. Consider the function $f(x)= rac{|x-1|}{x+1}$ defined on the closed interval $\left[ rac{R-1}{R+1},  rac{R+1}{R-1} ight]$. Taking derivatives, it is elementary to verify that $f(x)$ is increasing in the interval $1< x <  rac{R+1}{R-1}$, while it is decreasing in the interval $ rac{R-1}{R+1}< x <1$. Furthermore, noting that $f(1)=0$, it is direct that {\small  egin{align}
onumber \sup
olimits_{ eta \in {\mathbb{U}_{m Ising}}(R,\varepsilon)}f( eta)= f\left( rac{R-1+\varepsilon}{R+1-\varepsilon}ight)= f\left( rac{R+1-\varepsilon}{R-1+\varepsilon}ight) = rac{1-\varepsilon}{R} \enspace. \end{align} } We conclude that \eqref{eq:Target4thrm:SI4Ising} implies \eqref{eq:lemma:IsingInfNormBound}. It remains to show that \eqref{eq:Target4thrm:SI4Ising} is true. Since $ rac{\partial }{\partial x_{i}}H_d(x_1, \ldots, x_d)=h(x_{i})$, it suffices to show that for any $x\in [-\infty, +\infty]$ we have that {\small  egin{align} \abs{ h(x)} &\leq  rac{\abs{1- eta } }{1+ eta} \enspace. \end{align} } For the distribution we consider here, the function $h(\cdot)$ is given by  egin{align} h(x) & =- rac{(1- eta^2) \exp(x)}{( eta \exp(x)+1)(\exp(x)+ eta)} \enspace. \end{align} From the above we get that {\small  egin{align} \abs{h(x)} & =  rac{\abs{1- eta^2}\exp(x)}{(b \exp(x) +1)(b+ \exp(x))} \ = \  rac{\abs{1- eta^2 }}{ eta^2+1 + eta (\exp(-x)+\exp(x) ) } \enspace. 
onumber \end{align} } It is straightforward to verify that $\phi(x)=e^{-x}+e^{x}$ is convex and for any $x\in [-\infty, +\infty]$ and attains its minimum at $x=0$, i.e., we have that $\phi(x)\geq 2$. Consequently, we get {\small  egin{align} 
onumber \abs{h(x)} & \leq  rac{\abs{1- eta^2}}{ eta^2+1 +2 eta } \ = \  rac{\abs{1- eta}}{1+ eta} \enspace, \end{align} } for any $x\in [-\infty, +\infty]$. The above proves that \eqref{eq:TargetB4thrm:SI4Ising} is true and concludes our proof.

For two distributions $\upnu$ and $\hat{\upnu}$ on the discrete set $\Omega$, the {\em total variation distance} satisfies  egin{align}
onumber 
orm{\upnu-\hat{\upnu}}{tv} &=(1/{2}) \ { \sum
olimits_{x\in \Omega} }\abs{\upnu(x)-\hat{\upnu}(x)} \enspace . \end{align}

Recall that set $\iris{{\mathcal{E}}}_{\Lambda,k}$ consists of the self-avoiding walks of length $k$ in $G$ which do not intersect with set $\Lambda$. Let $\mathcal{J}$ be the $\iris{{\mathcal{E}}}_{\Lambda,k}	imes \iris{{\mathcal{E}}}_{\Lambda,k}$ matrix such that, for any $P,Q\in \iris{{\mathcal{E}}}_{\Lambda, k}$, the entry $\mathcal{J}(P,Q)$ is defined as follows: Let $w$ and $u$ be the starting vertices of $P$ and $Q$, respectively. If $P$ and $Q$ are not compatible, i.e., ${m dist}_G(u,w)< 2k$, we let $\mathcal{J}(P,Q)=0$. For $P$ and $Q$ which are compatible, we consider graph $\gext{G}{P,Q}$, the $(P,Q)$-extension of $G$, and let $T_{P,Q}=T_{m SAW}(\gext{G}{P,Q},w)$. We let  egin{align}
onumber \mathcal{J}(P,Q)&= \sum
olimits_{\ell \geq 2k}\delta^{\ell}	imes \abs{ \widehat{	t A}(u,\ell)} \enspace, \end{align} where we let set $\widehat{	t A}(u,\ell)$ consist of all copies of vertex $u$ in $T_{P,Q}$ which correspond to self-avoiding walks of length $\ell$ in $\gext{G}{P,Q}$.  egin{lemma} We have $\abs{\applegreen{{\mathcal{L}}}^{\Lambda,	au}_{G,k}} \leq \mathcal{J}$, where the inequality is entry-wise. \end{lemma} The proof of \Cref{lemma:eq:CLVsCJEntrywise} appears in \Cref{sec:lemma:eq:CLVsCJEntrywise}. As per standard notation, $\abs{\applegreen{{\mathcal{L}}}^{\Lambda,	au}_{G,k}}$ in \Cref{lemma:eq:CLVsCJEntrywise} corresponds to the matrix having entries $\abs{\applegreen{{\mathcal{L}}}^{\Lambda,	au}_{G,k}(P,Q)}$. \Cref{proposition:CINorm2VsCLNorm2} implies that there are constants $c_1,c_2>0$ such that  egin{align} 
orm{ {\mathcal{I}}^{\Lambda,	au}_G}{2} &\leq c_1+ c_2 \cdot 
orm{\abs{\applegreen{{\mathcal{L}}}^{\Lambda,	au}_{G,k}}}{2} \ \leq \ c_1+ c_2 \cdot 
orm{ \mathcal{J}}{2} \enspace. \end{align} The second inequality follows from \Cref{lemma:eq:CLVsCJEntrywise} and the observation that $\abs{\applegreen{{\mathcal{L}}}^{\Lambda,	au}_{G,k}}$ and $\mathcal{J}$ have non-negative entries.  egin{proposition} We have  egin{align} 
orm{ \mathcal{J}}{2} &\leq \sum 
olimits_{\ell\geq k} \delta^{\ell+k} \cdot 
orm{ ( \cadmiumgreen{\UpH}_{G,k} )^{\ell}}{2} \enspace. \end{align} \end{proposition} The proof of \Cref{prop:CJVskNBM} appears in \Cref{sec:prop:CJVskNBM}. \Cref{thrm:L2InflRedux2KNBTM} follows by plugging \eqref{eq:thrm:DomOfInflB} into \eqref{eq:IVsJ2Norm} and setting $C_1=c_1$ and $C_2=c_2\cdot \delta^{k}$. \hfill $\square$

For a vector ${ f v}\in \mathbb{R}^{N}_{\geq 0}$, and $r \in \mathbb{R}$, we let vector ${ f v}^{r}$ be such that ${ f v}^{r}(i)=({ f v}(i))^{r}$, for $1\leq i \leq N$. Also, when there is no danger of confusion, we abbreviate $\applegreen{{\mathcal{L}}}^{\Lambda,	au}_{G,k}$ to $osegold{{\mathcal{L}}}$. For integer $\ell\geq 2k$, we let $\mathcal{D}_{\ell}$ be the $\iris{{\mathcal{E}}}_{\Lambda,k}	imes \iris{{\mathcal{E}}}_{\Lambda,k}$ matrix such that for $P,Q \in \iris{{\mathcal{E}}}_{\Lambda,k}$, the entry $\mathcal{D}_{\ell}(P,Q)$ is defined as follows: Let $w$ and $u$ be the starting vertices of $P$ and $Q$, respectively. Assume, first, that $P$ and $Q$ are compatible, i.e., ${m dist}_G(w,u)\geq 2k$. Let $\gext{G}{P,Q}$ and $\upzeta^{P,Q}$ be the $\{P,Q\}$-extensions of $G$ and $\mu^{\Lambda,	au}_G$, respectively. Also, let $\cadmiumgreen{T_{P,Q}}=T_{m SAW}(G_{P,Q}, w)$ and the weights $\{ \upalpha_{P,Q}(e)\}$ are obtained as specified in \eqref{def:OfInfluenceWeights} with respect to $\upzeta^{P,Q}$. We let  egin{align}
onumber \mathcal{D}_{\ell}(P, Q) &=\sum
olimits_{W\in \cadmiumgreen{T_{P,Q}}: \abs{W}=\ell} \prod
olimits_{e\in W} \abs{\upalpha_{P,Q}(e)} \enspace, \end{align} where $W$ varies over all the paths of length $\ell$ from the root to the copies of $u$ in $\cadmiumgreen{T_{P,Q}}$ that correspond to self-avoiding walks. For non-compatible walks $P$ and $Q$, we let $\mathcal{D}_{\ell}(P, Q) =0$. From the definitions of the extended influence matrix $osegold{{\mathcal{L}}}$ and $ \mathcal{D}_{\ell}$, it is not hard to verify the entry-wise inequality $\abs{osegold{{\mathcal{L}}}} \leq \sum
olimits_{\ell\geq 2k} \mathcal{D}_{\ell}$, which implies  egin{align}
onumber 
orm{ \abs{osegold{{\mathcal{L}}}}}{2\darkmagenta{s}} & \leq \sum
olimits_{\ell\geq 2k} 
orm{ \mathcal{D}_{\ell}}{2\darkmagenta{s}}\enspace. \end{align} In light of the above, \Cref{thrm:InfNormBoundHConj} follows by showing that there exists a constant $\widehat{c}\geq 1$ such that  egin{align} 
orm{ \mathcal{D}_{\ell}}{2\darkmagenta{s}} &\leq \widehat{c} \cdot \left( {	extstyle \left( rac{1-\varepsilon/2}{\uprho}ight)^{\ell-k}} \cdot 
orm{ (\cadmiumgreen{\UpH}_{G,k})^{{\ell-k}}}{2} ight)^{1/\darkmagenta{s}} &  orall \ell\geq 2k \enspace. \end{align} Before showing that \eqref{eq:Target4thrm:InfNormBoundHConjLL} is true, we introduce a few concepts and establish some useful technical results. For $\ell\geq 2k$, we let $ed{\UpZ}^{(\ell)}$ be the $\iris{{\mathcal{E}}}_{\Lambda,k}	imes \iris{{\mathcal{E}}}_{\Lambda,k}$ matrix such that for $P,Q \in \iris{{\mathcal{E}}}_{\Lambda,k}$, the entry $ed{\UpZ}^{(\ell)}(P,Q)$ is defined as follows: Let $w$ and $u$ be the starting vertices of $P$ and $Q$, respectively. For $P$ and $Q$ which are compatible, we consider $ yzantine{\overline{T}}=T_{m SAW}(\gext{G}{P}, w)$ and let  egin{align}
onumber ed{\UpZ}^{(\ell)}(P, Q) &=\# 	extrm{copies of walk $Q$ in $ yzantine{\overline{T}}$ which is at distance $\ell$ from the root} \enspace. \end{align} For vertex $x$ in $ yzantine{\overline{T}}$, which is connected to the root of the tree with path $W=x_0, \ldots, x_{\ell}$, i.e., $x_0$ is the root and $x_{\ell}$ is $x$; we say that $x$ is a copy of walk $Q=z_0,\ldots, z_{k}$, if $x_{\ell-i}$ is a copy of $z_{i}$, for all $i=0,\ldots, k$. For non-compatible $P$ and $Q$, we have $ed{\UpZ}^{(\ell)}(P, Q) =0$. For integer $\ell\geq 2k$ and $\iris{{ f q}} \in \mathbb{R}^{\iris{{\mathcal{E}}}_{\Lambda,k}}_{\geq 0}$, let vectors $\upf_{\iris{{ f q}}, \ell},\upg_{\iris{{ f q}}, \ell}, \upk_{\iris{{ f q}}, \ell} \in \mathbb{R}^{\iris{{\mathcal{E}}}_{\Lambda,k}}_{\geq 0}$ be defined as follows: We let  egin{align} \upf_{\iris{{ f q}}, \ell}=\mathcal{D}_{\ell}\cdot \iris{{ f q}} \enspace. \end{align} We also let  egin{align} \upg_{\iris{{ f q}}, \ell} &= \left( {	extstyle  rac{1-\varepsilon/2}{\uprho}} ight)^{\ell/\darkmagenta{s}} \cdot \left( ed{\UpZ}^{(\ell)}\cdot \iris{{ f q}}^{\darkmagenta{s}}ight)^{1/\darkmagenta{s}} \enspace. \end{align} Similarly, we let  egin{align} \upk_{\iris{{ f q}}, \ell}&= {	extstyle \left( rac{1-\varepsilon/2}{\uprho}ight)^{\ell/\darkmagenta{s}} } \cdot \left( ( ( \cadmiumgreen{\UpH}_{G,k})^{\ell-k}\cdot \UpR)_{\iris{{\mathcal{E}}}_{\Lambda,k}} \cdot \iris{{ f q}}^{\darkmagenta{s}}ight)^{1/\darkmagenta{s}} \enspace, \end{align} where $\UpR$ is the $\iris{{\mathcal{E}}}_{k}	imes \iris{{\mathcal{E}}}_{k}$ involutionary matrix defined in \eqref{def:OfInvolutation}. Also, $(( \cadmiumgreen{\UpH}_{G,k})^{{\ell-k}}\cdot \UpR)_{\iris{{\mathcal{E}}}_{\Lambda,k}}$ corresponds to the principle submatrix of $( \cadmiumgreen{\UpH}_{G,k})^{\ell-k}\cdot \UpR$ induced by the elements in $\iris{{\mathcal{E}}}_{\Lambda, k}\subseteq \iris{{\mathcal{E}}}_{k}$.  egin{proposition} For $k\geq 1$, there exists a constant $\widehat{c}_0\geq 1$ such that, for any $\ell\geq 2k$ and any $\iris{{ f q}} \in \mathbb{R}^{\iris{{\mathcal{E}}}_{\Lambda,k}}_{\geq 0}$  egin{align} \upf^{\darkmagenta{s}}_{\iris{{ f q}}, \ell} &\leq \widehat{c}_0 \cdot \upg^{\darkmagenta{s}}_{\iris{{ f q}}, \ell} \enspace, \end{align} where the inequality between the two vectors is entry-wise. \end{proposition} The proof of \Cref{thrm:HC-VEntryBound} appears in \Cref{sec:thrm:HC-VEntryBound}. Letting ${ f 0}\in \mathbb{R}^{\iris{{\mathcal{E}}}_{\Lambda,k}}$ be the all-zeros vector, for any $\iris{{ f q}} \in \mathbb{R}^{\iris{{\mathcal{E}}}_{\Lambda,k}}_{\geq 0}$, for any $\ell\geq 2k$, we have  egin{align} { f 0}\leq \upf_{\iris{{ f q}}, \ell} \leq \widehat{c}_0\cdot \upg_{\iris{{ f q}}, \ell} \leq \widehat{c}_0\cdot \upk_{\iris{{ f q}}, \ell}\enspace, \end{align} where the above inequalities are entry-wise, while $\widehat{c}_0$ is from \Cref{thrm:HC-VEntryBound}. To see why \eqref{eq:GKVecDom} is true, note the following: The first inequality implies that the entries of $f_{\iris{{ f q}},\ell}$, which is defined in \eqref{eq:DefOfFvec}, are non-negative, which is true since both $\mathcal{D}_{\ell}$ and $\iris{{ f q}}$ have non-negative entries. The second inequality follows from the fact that the entries of $\upg_{\iris{{ f q}},\ell}$ are non-negative and \Cref{thrm:HC-VEntryBound}. The third inequality follows from the observation that each entry $ed{\UpZ}^{(\ell)}(P, Q)$ is upper bounded by the number of $k$-non-backtracking walks of length $\ell-k$ from $P$ to $Q$. Let $\iris{{ f q}}^{\star}=\iris{{ f q}}^{\star}(\ell) \in \mathbb{R}^{\iris{{\mathcal{E}}}_{\Lambda,k}}_{\geq 0}$ be such that  egin{align} 
orm{ \iris{{ f q}}^{\star}}{2\darkmagenta{s}}&=1& 	extrm{and} && 
orm{\mathcal{D}_{\ell}}{2\darkmagenta{s}}&=
orm{ \mathcal{D}_{\ell}\cdot \iris{{ f q}}^{\star}}{2\darkmagenta{s}} \enspace. \end{align} We let $\upf^{\star}_{\ell}=\upf_{\iris{{ f q}}^{\star}, \ell}$, while let $\upg^{\star}_{\ell}=\upg_{\iris{{ f q}}^{\star}, \ell}$ and $\upk^{\star}_{\ell}=\upk_{\iris{{ f q}}^{\star}, \ell}$. Noting that $\iris{{ f q}}^{\star}$ has non-negative entries because the entries of $\mathcal{D}_{\ell}$ are non-negative, from \eqref{eq:GKVecDom}, we get  egin{align} 
orm{ \mathcal{D}_{\ell}}{2\darkmagenta{s}}&=
orm{ \upf^{\star}_{\ell}}{2\darkmagenta{s}} \leq \widehat{c}_0 \cdot 
orm{ \upg^{\star}_{\ell}}{2\darkmagenta{s}} \leq \widehat{c}_0 \cdot 
orm{ \upk^{\star}_{\ell}}{2\darkmagenta{s}} \enspace. \end{align} Let vector $\upk^{\darkmagenta{s},\star}_{\ell}$ be such that $\upk^{\darkmagenta{s},\star}_{\ell}(P)=({\upk}^{\star}_{\ell}(P))^{\darkmagenta{s}}$, for all $P\in \iris{{\mathcal{E}}}_{\Lambda,k}$. Similarly, define $\iris{{ f q}}^{\darkmagenta{s},\star}$ such that $\iris{{ f q}}^{\darkmagenta{s},\star}(P)=({\iris{{ f q}}}^{\star}(P))^{\darkmagenta{s}}$. From the definition of the corresponding vectors, we have  egin{align} 
norm{ \upk^{\star}_{\ell}}{2\darkmagenta{s}}{2\darkmagenta{s}}&=
norm{ \upk^{\darkmagenta{s},\star}_{\ell}}{2}{2}& 	extrm{and} && 
orm{ \iris{{ f q}}^{\darkmagenta{s},\star}}{2}=
orm{ \iris{{ f q}}^{\star}}{2\darkmagenta{s}}=1 \enspace. \end{align} Using the above observation, we have  egin{align} 
norm{ \upk^{\star}_{\ell}}{2\darkmagenta{s}}{2\darkmagenta{s}}=
